'use strict';
const fs=require('fs'),os=require('os'),path=require('path'),crypto=require('crypto');
const {spawnSync}=require('child_process');
const root=process.env.GITHUB_WORKSPACE||process.cwd();
const evidence=fs.mkdtempSync(path.join(process.env.RUNNER_TEMP||os.tmpdir(),'foundation-work-project-'));
const pkg=path.join(root,'system-master','foundation-spine','work-project');
const classes=path.join(evidence,'classes'); fs.mkdirSync(classes,{recursive:true});
function run(cmd,args,file){const r=spawnSync(cmd,args,{cwd:root,encoding:'utf8',shell:false,windowsHide:true,env:process.env});const out=(r.stdout||'')+(r.stderr||'');if(file)fs.writeFileSync(path.join(evidence,file),out,'utf8');if(r.error||r.status!==0)throw new Error(`${cmd} ${args.join(' ')} failed: ${r.error?r.error.message:`exit ${r.status}`}\n${out}`);return out.trim();}
function java(dir){let out=[];for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())out=out.concat(java(p));else if(e.isFile()&&e.name.endsWith('.java'))out.push(p);}return out.sort();}
function shaFile(p){return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');}
function trace(){const t=JSON.parse(fs.readFileSync(path.join(pkg,'WORK-PROJECT-BUILD-TRACEABILITY.json'),'utf8'));if(t.package_id!=='CORE-WORK-PROJECT-BUILD-001')throw new Error('package id mismatch');if(t.design_lock_commit!=='6a3a044c317adc354f6a91e1b3576d34481e2ccb')throw new Error('design lock mismatch');if(t.upstream_keel_freeze_commit!=='40cf431fd2ad4857e126a95715a449b7325515de')throw new Error('Keel freeze mismatch');if(t.isolated_case_denominator!==64||t.unaccounted_requirement_count!==0)throw new Error('denominator/accounting mismatch');if(!Array.isArray(t.invariants)||t.invariants.length!==24)throw new Error('invariant count mismatch');const ids=new Set(t.invariants.map(x=>x.id));if(ids.size!==24)throw new Error('duplicate invariant ids');for(let i=1;i<=24;i++)if(!ids.has(`WP-${String(i).padStart(2,'0')}`))throw new Error(`missing WP-${String(i).padStart(2,'0')}`);for(const row of t.invariants)for(const f of ['requirement','implementation','tests'])if(!row[f]||!String(row[f]).trim())throw new Error(`${row.id} missing ${f}`);if(!Array.isArray(t.external_evidence_fences)||t.external_evidence_fences.length<6)throw new Error('evidence fences missing');fs.writeFileSync(path.join(evidence,'traceability.json'),JSON.stringify({package_id:t.package_id,invariant_count:t.invariants.length,isolated_case_denominator:t.isolated_case_denominator,unaccounted_requirement_count:t.unaccounted_requirement_count,external_evidence_fences:t.external_evidence_fences,result:'PASS'},null,2)+'\n');}
try{
 const subject=run('git',['rev-parse','HEAD']);run('git',['merge-base','--is-ancestor','6a3a044c317adc354f6a91e1b3576d34481e2ccb','HEAD']);run('git',['merge-base','--is-ancestor','40cf431fd2ad4857e126a95715a449b7325515de','HEAD']);
 fs.writeFileSync(path.join(evidence,'subject.txt'),[`component=Foundation Work Project Control`,`commit=${subject}`,`design_lock=6a3a044c317adc354f6a91e1b3576d34481e2ccb`,`upstream_keel_freeze=40cf431fd2ad4857e126a95715a449b7325515de`,`qualification_class=HOSTED_PORTABLE_REFERENCE_WORK_PROJECT_AUTHORITY_MECHANICS`,`a01_native_human_production_endurance=NOT_CLAIMED`,''].join('\n'));
 run('java',['-version'],'java-version.txt');run('javac',['-version'],'javac-version.txt');trace();
 const inventory=fs.readFileSync(path.join(pkg,'WORK-PROJECT-RECOVERY-INVENTORY-001.md'),'utf8');if(!inventory.includes('RECOVERY INVENTORY CLOSED'))throw new Error('recovery inventory not closed');
 const lock=fs.readFileSync(path.join(pkg,'WORK-PROJECT-DESIGN-LOCK-001.md'),'utf8');if(!lock.includes('DESIGN LOCKED')||!lock.includes('64-case isolated gate'))throw new Error('design lock predicates missing');
 const sources=java(path.join(pkg,'src','main','java')),tests=java(path.join(pkg,'src','test','java')),all=[...sources,...tests];if(sources.length!==1||tests.length!==1)throw new Error('unexpected source/test subject cardinality');
 fs.writeFileSync(path.join(evidence,'source-digests.json'),JSON.stringify(Object.fromEntries(all.map(f=>[path.relative(root,f),shaFile(f)])),null,2)+'\n');
 run('javac',['--release','21','-Xlint:all,-try','-Werror','-d',classes,...all],'compile.txt');
 const isolated=run('java',['-cp',classes,'org.systemmaster.foundation.workproject.WorkProjectAuthorityQualificationTest'],'work-project-isolated.txt');if(!isolated.includes('PASS FOUNDATION_WORK_PROJECT cases=64'))throw new Error('64-case predicate missing');
 const keel=run('node',['.github/scripts/foundation-keel-qualify.js'],'foundation-upstream-cumulative.txt');if(!keel.includes('PASS FOUNDATION_KEEL_HOSTED_PORTABLE')||!keel.includes('PASS FOUNDATION_ROOT_IDENTITY_CONTRACTS_KEEL_CUMULATIVE'))throw new Error('upstream cumulative Foundation predicate missing');
 fs.writeFileSync(path.join(evidence,'result.txt'),'result=PASS\nisolated_cases=64\nwork_project_invariants=24\nunaccounted=0\nupstream_foundation_cumulative=PASS\na01_native_human_production_endurance=NOT_CLAIMED\n');
 console.log(isolated);console.log('PASS FOUNDATION_WORK_PROJECT_HOSTED_PORTABLE');console.log('PASS FOUNDATION_ROOT_IDENTITY_CONTRACTS_KEEL_WORK_PROJECT_CUMULATIVE');console.log(`evidence_dir=${evidence}`);
}catch(e){fs.writeFileSync(path.join(evidence,'result.txt'),'result=FAIL_OR_INCOMPLETE\n');fs.writeFileSync(path.join(evidence,'failure.txt'),`${e&&e.stack?e.stack:String(e)}\n`);console.error(e&&e.stack?e.stack:e);console.error(`evidence_dir=${evidence}`);process.exit(1);}
